-- Synthetic PostgreSQL subjects; all fixtures, changes and history roll back.
begin;
do $$
declare c uuid;owner_id uuid;manager_id uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();outside_id uuid:=gen_random_uuid();
 manager_person uuid;staff_person uuid;manager_email text;staff_email text;outside_email text;zone text;day date;tin timestamptz;tout timestamptz;
 shift_id uuid;parent_id uuid;before_record public.attendance;computed_basis jsonb;proposal jsonb;decision jsonb;r uuid;stale_id uuid;cancelled_id uuid;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.overtime_request(jsonb)') is null then raise exception 'Expected initialized overtime deployment.';end if;
 select id,companies.owner_id,timezone into strict c,owner_id,zone from public.companies;
 day:=(clock_timestamp() at time zone zone)::date-12;tin:=(day+time '08:17') at time zone zone;tout:=(day+time '23:00') at time zone zone;
 manager_email:='qa-overtime-manager-'||manager_id||'@example.invalid';staff_email:='qa-overtime-staff-'||staff_id||'@example.invalid';outside_email:='qa-overtime-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(manager_id,manager_email,clock_timestamp()),(staff_id,staff_email,clock_timestamp()),(outside_id,outside_email,clock_timestamp());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into manager_person from public.company_members where user_id=manager_id;select employee_id into staff_person from public.company_members where user_id=staff_id;
 update public.employees set joined_on='2020-01-01',reports_to=manager_person where id=staff_person;
 shift_id:=public.save_shift_template('{"id":null,"expected_revision":null,"name":"Synthetic rollback overtime shift","days":[1,2,3,4,5,6,7],"start_minute":480,"end_minute":1020,"works_on_holidays":true,"active":true,"break_rules":[]}');
 perform public.assign_shift(jsonb_build_object('employee_id',staff_person,'template_id',shift_id,'expected_template_revision',0,'expected_sequence',0,'effective_on',day,'expected_timezone',zone,'reason','Synthetic rollback overtime schedule'));
 parent_id:=public.correct_attendance(jsonb_build_object('attendance_id',null,'employee_id',staff_person,'work_date',day,'checked_in_at',tin,'checked_out_at',tout,'expected_revision',null,'reason','Synthetic rollback overtime attendance'));
 perform public.manage_attendance_break('record',jsonb_build_object('attendance_id',parent_id,'expected_parent_revision',0,'name','Synthetic outside unpaid break','paid',false,'started_at',(day+time '17:15') at time zone zone,'ended_at',(day+time '17:30') at time zone zone,'reason','Synthetic rollback actual break'));
 select * into strict before_record from public.attendance where id=parent_id;
 execute 'reset role';computed_basis:=hris_private.overtime_basis(before_record);assert (computed_basis->>'minutes')::integer>=60,'Expected sufficient saved-rule overtime under current company policy';execute 'set local role authenticated';
 proposal:=jsonb_build_object('operation','submit','attendance_id',parent_id,'expected_revision',0,'expected_breaks',(select jsonb_agg(jsonb_build_object('id',b.id,'revision',b.revision) order by b.id) from public.attendance_breaks b where attendance_id=parent_id and not voided),'expected_candidate_minutes',computed_basis->'minutes','minutes',60,'reason','Synthetic rollback overtime request','employee_id',manager_person,'actor_id',owner_id,'status','approved','approved_minutes',999,'basis','{}'::jsonb);
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 begin perform public.overtime_request(proposal||jsonb_build_object('minutes',(computed_basis->>'minutes')::integer+1));raise exception 'Candidate cap bypassed';exception when check_violation then null;end;
 r:=public.overtime_request(proposal);
 assert (select employee_id=staff_person and submitted_by=staff_id and status='pending' and requested_minutes=60 and approved_minutes is null and overtime_requests.basis=computed_basis from public.overtime_requests where id=r),'Protected request identity, state or basis forged';
 decision:=jsonb_build_object('operation','approve','request_id',r,'expected_revision',0,'minutes',45,'reason','Synthetic rollback Manager partial approval');
 begin perform public.overtime_request(decision);raise exception 'Own approval allowed';exception when insufficient_privilege then null;end;
 begin update public.overtime_requests set status='approved',approved_minutes=60 where id=r;raise exception 'Direct request edit allowed';exception when insufficient_privilege then null;end;
 begin delete from public.overtime_events where request_id=r;raise exception 'Decision history deletion allowed';exception when insufficient_privilege then null;end;
 begin perform hris_private.overtime_basis(before_record);raise exception 'Private calculation helper executable';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);assert not exists(select 1 from public.overtime_requests where id=r),'Unrelated Manager read request';assert not exists(select 1 from public.overtime_events where request_id=r),'Unrelated Manager read history';
 begin perform public.overtime_request(decision);raise exception 'Unrelated approval allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);assert exists(select 1 from public.overtime_events where request_id=r),'Current Manager cannot read scoped history';perform public.overtime_request(decision);
 assert (select status='approved' and approved_minutes=45 and revision=1 from public.overtime_requests where id=r),'Partial approval missing';
 assert (select to_jsonb(a)=to_jsonb(before_record) from public.attendance a where id=parent_id),'Approval edited attendance facts';
 assert (select count(*)=2 from public.overtime_events where request_id=r),'Submission or approval history missing';
 assert (select actor_id=manager_id and actor_role='manager' and before_status='pending' and approved_minutes=45 from public.overtime_events where request_id=r and status='approved'),'True Manager attribution lost';
 begin perform public.overtime_request(decision);raise exception 'Repeated approval accepted';exception when sqlstate 'PT409' then null;end;
 perform set_config('request.jwt.claim.sub',staff_id::text,true);begin perform public.overtime_request(proposal);raise exception 'Duplicate active request accepted';exception when sqlstate 'PT409' then null;end;
 decision:=decision||jsonb_build_object('operation','revoke','expected_revision',1,'reason','Synthetic rollback authorization revoked');
 begin perform public.overtime_request(decision);raise exception 'Own revocation allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);perform public.overtime_request(decision);
 assert (select status='revoked' and approved_minutes=45 and revision=2 from public.overtime_requests where id=r),'Revocation erased previous authorization';
 assert (select before_status='approved' and before_approved_minutes=45 and approved_minutes=45 from public.overtime_events where request_id=r and status='revoked'),'Revocation history incomplete';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);stale_id:=public.overtime_request(proposal);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform public.manage_attendance_break('record',jsonb_build_object('attendance_id',parent_id,'expected_parent_revision',0,'name','Synthetic later paid break','paid',true,'started_at',(day+time '10:00') at time zone zone,'ended_at',(day+time '10:15') at time zone zone,'reason','Synthetic rollback concurrent basis change'));
 perform set_config('request.jwt.claim.sub',manager_id::text,true);decision:=decision||jsonb_build_object('operation','approve','request_id',stale_id,'expected_revision',0);
 begin perform public.overtime_request(decision);raise exception 'Stale break basis approved';exception when sqlstate 'PT409' then null;end;
 assert (select status='pending' from public.overtime_requests where id=stale_id),'Failed approval changed status';assert (select count(*)=1 from public.overtime_events where request_id=stale_id),'Failed approval wrote history';
 perform public.overtime_request(decision||jsonb_build_object('operation','reject','reason','Synthetic stale request rejected'));
 perform set_config('request.jwt.claim.sub',staff_id::text,true);proposal:=proposal||jsonb_build_object('expected_breaks',(select jsonb_agg(jsonb_build_object('id',b.id,'revision',b.revision) order by b.id) from public.attendance_breaks b where attendance_id=parent_id and not voided));cancelled_id:=public.overtime_request(proposal);
 perform public.overtime_request(jsonb_build_object('operation','cancel','request_id',cancelled_id,'expected_revision',0,'reason','Synthetic requester cancellation'));
 assert (select status='cancelled' from public.overtime_requests where id=cancelled_id),'Own cancellation missing';
 assert (select to_jsonb(a)=to_jsonb(before_record) from public.attendance a where id=parent_id),'Overtime workflow changed actual attendance';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform public.save_company_account(staff_id,staff_email,'employee',false,null,null);
 perform set_config('request.jwt.claim.sub',staff_id::text,true);assert not exists(select 1 from public.overtime_requests),'Disabled member read overtime';assert not exists(select 1 from public.overtime_events),'Disabled member read history';begin perform public.overtime_request(proposal);raise exception 'Disabled submit allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';begin perform public.overtime_request(proposal);raise exception 'Anonymous submit allowed';exception when insufficient_privilege then null;end;
 begin perform * from public.overtime_requests;raise exception 'Anonymous read allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Exposed public security definer';
 assert (select count(*)=2 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('overtime_requests','overtime_events') and t.relrowsecurity),'Overtime RLS missing';
end;$$;
rollback;
